require "Vehicles/ISUI/ISCarMechanicsOverlay"

local PREFIX = "nev_lil6_"
local car = { imgPrefix = PREFIX, x = 10, y = 0, PartList = {} }
ISCarMechanicsOverlay.CarList["Base.NEV_LiL6"] = car

-- The image of every part goes into this car's own PartList (vanilla draws
-- props.PartList[id] instead of the global entry, ISVehicleMechanics:928).
-- The global PartList only gets our hit rect: vanilla draws a part only when
-- a global entry exists and reads hit rects from it, so ids vanilla lacks get
-- an entry that draws nothing for other cars (DESIGN 13.5-21; REVIEW 3.1-4:
-- a global TrunkDoor entry drew trunk.png a second time on the vanilla SUV).
local function add(part, img, x, y, x2, y2)
    car.PartList[part] = { img = img }
    local entry = ISCarMechanicsOverlay.PartList[part]
    if entry == nil then
        entry = { multipleImg = true, img = {}, vehicles = {} }
        ISCarMechanicsOverlay.PartList[part] = entry
    end
    entry.vehicles = entry.vehicles or {}
    entry.vehicles[PREFIX] = { x = x, y = y, x2 = x2, y2 = y2 }
end

